import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, uniform } from 'three/tsl';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  // Create a plane geometry sized to atlas region aspect ratio (512×320 = 1.6:1)
  const geometry = new THREE.PlaneGeometry(1.6, 1.0);

  // Load the sprite texture
  let material;
  const texturePromise = ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
    // Normalize UV to atlas region: source (0,0,512,320) in a full atlas
    // Assuming full atlas is 512×512, region is top-left corner
    const uvOffset = new THREE.Vector2(0, 0.375); // y offset for 320px from 512 height
    const uvScale = new THREE.Vector2(1.0, 0.625); // scale for 320/512 height

    texture.offset.copy(uvOffset);
    texture.repeat.copy(uvScale);
    texture.flipY = false;

    material.map = texture;
    material.needsUpdate = true;
  });

  // Create material with TSL nodes
  const mapNode = uniform(null);
  material = new MeshBasicNodeMaterial({
    colorNode: mapNode,
    transparent: true,
    depthTest: true,
    depthWrite: true,
  });

  // After texture loads, update the mapNode
  texturePromise.then(() => {
    // The material.map is set above; TSL nodes will read it
    material.needsUpdate = true;
  });

  // Create the mesh
  const mesh = new THREE.Mesh(geometry, material);
  mesh.position.set(-3.2, 1, 0.06);
  mesh.rotation.set(0, 0, 0);
  mesh.scale.set(1, 1, 1);

  // Billboard toward camera (look at camera z-axis)
  mesh.lookAt(0, 0, 10);

  // Create the return group
  const group = new THREE.Group();
  group.add(mesh);

  // Attach text label "Collection 1" above/beside the sprite
  const textLabel = ctx.fontAtlas.createText('Collection 1', {
    fontSize: 39,
    color: '#e8ecf2',
    align: 'center',
  });
  textLabel.position.set(0, 0.65, 0.01);
  group.add(textLabel);

  // Setup cleanup
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (material.map) {
      material.map.dispose();
    }
  };

  group.userData.handlers = {};

  return group;
}
